cand={}
for i in range(0,3):
  for j in [-2,-1,0,1,2,3]:
    for k in [0,1,2]:
      if i==0 and j==0 and k==0: continue
      cand[f"t^{i} P^{j} L^{k}"]=t**i*P**j*L**k
names=list(cand); M=np.column_stack([cand[n] for n in names])
