import numpy as np
L=np.log(P)
cols={};
for i in range(3):
  for j in [-1,0,1,2,3]:
    for k in [0,1]:
      cols[f"t^{i}P^{j}L^{k}"]=t**i*P**j*L**k
names=list(cols); X=np.column_stack([cols[n] for n in names])
